{
  "items": [
    {
      "slot": 1,
      "description": "Product SKU format:\n- Exactly two uppercase letters, but the letters I and O are not allowed.\n- Followed by exactly three digits.\n- Followed by a hyphen.\n- Followed by one uppercase letter (excluding I and O) and then one digit.\nThe whole string must match this format.",
      "regex": "/^[A-HJ-NP-Z]{2}\\d{3}-[A-HJ-NP-Z]\\d$/"
    },
    {
      "slot": 2,
      "description": "SKU format:\n- Begins with the literal prefix 'SKU-'.\n- Then exactly three uppercase letters.\n- Then a hyphen.\n- Then exactly four digits.\n- Optionally, a hyphen followed by exactly two uppercase letters (variant code).\nThe entire string must conform, with no other characters.",
      "regex": "/^SKU-[A-Z]{3}-\\d{4}(?:-[A-Z]{2})?$/"
    },
    {
      "slot": 3,
      "description": "Our issue tracker uses JIRA-style ticket references. A valid reference has a project code of two to five uppercase letters, followed by a hyphen, then a ticket number that is a positive integer without leading zeros.",
      "regex": "/^[A-Z]{2,5}-[1-9]\\d*$/"
    },
    {
      "slot": 4,
      "description": "We use ULIDs as order identifiers. A ULID is 26 characters long and uses Crockford's Base32 alphabet: digits and uppercase letters, but the letters I, L, O and U are never used.",
      "regex": "/^[0-9A-HJKMNP-TV-Z]{26}$/"
    },
    {
      "slot": 5,
      "description": "UUID version 4 format:\n- 8 hexadecimal digits, then a hyphen.\n- 4 hexadecimal digits, then a hyphen.\n- The digit 4, then 3 hexadecimal digits, then a hyphen.\n- One of the characters 8, 9, A, or B (case-insensitive), then 3 hexadecimal digits, then a hyphen.\n- 12 hexadecimal digits.\nHexadecimal digits may be uppercase or lowercase.",
      "regex": "/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "pin code 4 to 6 digits not all identical",
      "regex": "/^(?!(\\d)\\1+$)\\d{4,6}$/"
    },
    {
      "slot": 2,
      "description": "The string must be an API key consisting of the prefix 'sk_' followed by exactly 32 hexadecimal digits (0-9, a-f, A-F).",
      "regex": "/^sk_[0-9a-fA-F]{32}$/"
    },
    {
      "slot": 3,
      "description": "A passphrase must consist of at least four words, each word being one or more lowercase letters, separated by single spaces.",
      "regex": "/^[a-z]+(?: [a-z]+){3,}$/"
    },
    {
      "slot": 4,
      "description": "The password must be at least 10 characters long and must not contain the word 'password' in any case combination. It may contain any characters except line breaks.",
      "regex": "/^(?!.*password).{10,}$/i"
    },
    {
      "slot": 5,
      "description": "Our production API keys are issued with the prefix 'ak_live_' followed by a 32-character hexadecimal string (0-9, a-f) that must not start with a digit. We need to check if a given string matches this format.",
      "regex": "/^ak_live_(?![0-9])[0-9a-f]{32}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A decimal octet is an integer from 0 to 255, with no leading zeros unless it is the single digit 0.",
      "regex": "/^(0|[1-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$/"
    },
    {
      "slot": 2,
      "description": "A number in scientific notation consists of an optional sign, a mantissa that is either an integer or a decimal with at least one digit before and after the decimal point, the letter e or E, an optional sign, and an exponent that is a nonzero digit followed by zero or more digits, or a single zero.",
      "regex": "/^[-+]?\\d+(\\.\\d+)?[eE][-+]?(0|[1-9]\\d*)$/"
    },
    {
      "slot": 3,
      "description": "A signed decimal number consists of: an optional plus or minus sign; an integer part that is either the single digit zero or a nonzero digit followed by zero or more digits; and an optional fractional part consisting of a decimal point followed by one or more digits. No leading zeros are allowed in the integer part unless it is exactly zero.",
      "regex": "/^[-+]?(0|[1-9]\\d*)(\\.\\d+)?$/"
    },
    {
      "slot": 4,
      "description": "We need to validate the IP address octet field in our network configuration form. It should accept any whole number from 0 to 255, and leading zeros are allowed.",
      "regex": "/^(25[0-5]|2[0-4]\\d|1\\d{2}|0?\\d{1,2})$/"
    },
    {
      "slot": 5,
      "description": "A signed decimal number is valid if it consists of: an optional plus or minus sign; then either an integer part or a fractional part; the integer part, if present, is either the single digit zero or a nonzero digit followed by zero or more digits; the fractional part, if present, is a decimal point followed by one or more digits; at least one of the integer part or the fractional part must be present; no leading zeros are allowed in the integer part unless it is exactly zero.",
      "regex": "/^[-+]?((0|[1-9]\\d*)(\\.\\d+)?|\\.\\d+)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Valid CSS length: one or more decimal digits followed immediately by one of the units 'px', 'em', 'rem', or '%'. The unit must be lowercase. The entire string must be validated.",
      "regex": "/^[0-9]+(px|em|rem|%)$/"
    },
    {
      "slot": 2,
      "description": "Our design tool lets users paste HTML snippets. We need to check that a snippet contains at least one opening <div> tag. The tag may have attributes, including quoted values that contain > characters, and may span multiple lines. It must not be a self-closing tag (i.e., ending with '/>') or a closing tag.",
      "regex": "/<div(?=\\s|>)(?:[^>\"']|\"[^\"]*\"|'[^']*')*(?<!\\/)>/"
    },
    {
      "slot": 3,
      "description": "A data URI for an image: starts with 'data:image/', followed by the image subtype 'png', 'jpeg', or 'gif' (case-insensitive), then ';base64,', then a non-empty base64 string using the standard base64 alphabet (A-Z, a-z, 0-9, +, /), optionally ending with one or two '=' padding characters. The whole string must be on one line.",
      "regex": "/^data:image\\/(png|jpeg|gif);base64,[A-Za-z0-9+/]+={0,2}$/i"
    },
    {
      "slot": 4,
      "description": "Match a string that is a valid HTTP or HTTPS URL. It must start with http:// or https://, followed by a domain name that has at least one dot and a top-level domain of at least two letters. The domain may have subdomains. After the domain, an optional port number between 1 and 65535 may appear. Then an optional path starting with /, an optional query string starting with ?, and an optional fragment starting with # may follow. The string must not contain spaces.",
      "regex": "/^(https?):\\/\\/(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,}(?::(?:[1-9]\\d{0,3}|[1-5]\\d{4}|6[0-4]\\d{3}|65[0-4]\\d{2}|655[0-2]\\d|6553[0-5]))?(?:\\/[^\\s?#]*)?(?:\\?[^\\s#]*)?(?:#[^\\s]*)?$/i"
    },
    {
      "slot": 5,
      "description": "In our theme editor, users can specify CSS lengths for margins and paddings. We need to validate that the input is a valid CSS length. It can be a signed decimal number (with optional + or -) followed by a unit (px, em, rem, vh, vw, or %), or it can be the number zero without a unit. Units are case-insensitive.",
      "regex": "/^(?:[+-]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)(px|em|rem|vh|vw|%)|0)$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "spanish vat number uppercase es then one uppercase letter then seven digits then one uppercase letter or digit optional spaces",
      "regex": "/^ES\\s?[A-Z]\\s?\\d{7}\\s?[A-Z0-9]$/"
    },
    {
      "slot": 2,
      "description": "Our French shipping form needs to validate postal codes. It should accept either five digits, or for Corsica, starting with 2A or 2B followed by three digits. An optional space is allowed between the first two characters and the last three.",
      "regex": "/^(?:\\d{2}|2[AB])\\s?\\d{3}$/"
    },
    {
      "slot": 3,
      "description": "We need to check UK postcodes in the shipping form. It should accept the standard format: one or two letters, then a digit, then an optional letter or digit, then an optional space, then a digit followed by two letters.",
      "regex": "/^[A-Z]{1,2}\\d[A-Z\\d]?\\s?\\d[A-Z]{2}$/i"
    },
    {
      "slot": 4,
      "description": "We need to validate US ZIP codes in the checkout. The field should accept 5-digit ZIPs, 9-digit ZIPs without a separator, and ZIP+4 codes where the extra four digits are separated by either a hyphen or a single space. No other characters or extra spaces are allowed.",
      "regex": "/^(?:\\d{5}|\\d{9}|\\d{5}[ -]\\d{4})$/"
    },
    {
      "slot": 5,
      "description": "We need to validate French SIRET or SIREN numbers in our registration form. A SIREN is 9 digits and a SIRET is 14 digits.",
      "regex": "/^(?:\\d{9}|\\d{14})$/"
    }
  ]
}
